UNMET = "Not met yet — a stranger until the story brings them together in play (see the PARTY and MEETING rules)."


def heroine(cid, name, age, role, personality, look, history, style, sample, likes, goals, fears=None, dislikes=None):
    return {
        "id": cid,
        "name": name,
        "role": role,
        "personality": personality,
        "background": f"LOCKED VISUAL IDENTITY (must match every image): a {age}-year-old adult woman with {look} {history}",
        "goals": goals,
        "fears": fears or [],
        "likes": likes,
        "dislikes": dislikes or [],
        "speakingStyle": style,
        "sampleLine": sample,
        "relationshipWithUser": UNMET,
        "knowledge": [],
        "visualDesign": f"Photorealistic live-action fantasy photography. Same {age}-year-old adult woman every time: {look}",
    }


